{
  "segment_function": "conclusion",
  "claims": [
    {
      "claim": "The ideals of permanence, stability, and durability associated with homo faber have been sacrificed to the ideal of abundance associated with the animal laborans.",
      "claim_type": "author_position",
      "supporting_excerpt": "The ideals of homo faber , the fabricator of the world, which are permanence, stability, and durability, have been sacrificed to abundance, the ideal of the animal laborans.",
      "support_kind": "direct",
      "qualifications": [],
      "confidence": 1
    },
    {
      "claim": "A consumers' society is equivalent to a society of laborers because labor and consumption are two stages of the same biological necessity-driven process.",
      "claim_type": "author_position",
      "supporting_excerpt": "It is frequently said that we live in a consumers’ society, and since, as we saw, labor and consumption are but two stages of the same process, imposed upon man by the necessity of life, this is only another way of saying that we live in a society of laborers.",
      "support_kind": "direct",
      "qualifications": [],
      "confidence": 1
    }
  ],
  "definitions": [
    {
      "term": "animal laborans",
      "definition": "The laboring activity whose ideal is abundance and whose processes are characterized by endless repetition and the metabolism with nature."
    },
    {
      "term": "homo faber",
      "definition": "The fabricator of the world whose ideals are permanence, stability, and durability."
    }
  ],
  "distinctions": [
    {
      "item_a": "use objects",
      "item_b": "consumer goods",
      "distinction": "Use objects possess relative durability and allow for respect and preservation, whereas consumer goods are characterized by a swift coming and going and require rapid replacement and consumption."
    }
  ],
  "references_to_other_sections": [],
  "unresolved_context": [],
  "must_not_be_lost": [
    "The transition from a world of durable use objects to a consumers' society where everything is rapidly consumed.",
    "The emancipation of the laboring activity resulting in its undisputed predominance over other activities of the vita activa."
  ]
}

